quests[93006] = { id = 93006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorationsjagd", description = "Seid Ihr bereit für die heutige Herausforderung? Ich habe hier in der Nachbarschaft ein Stück aus meiner Sammlung versteckt. Um es zu finden, müsst Ihr lediglich dieses einfache Rätsel lösen:\n\nErde, Feuer, Rauch und Dampf.\nKlinge oder Pflug, die Wahl des Formers.\nSucht, wo das Metall sich biegt.\n\nViel Glück!", sourceObjective = "Löst das Rätsel und findet den Schatz.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
