quests[93104] = { id = 93104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorationsjagd", description = "Seid Ihr bereit für die heutige Herausforderung? Ich habe hier in der Nachbarschaft ein Stück aus meiner Sammlung versteckt. Um es zu finden, müsst Ihr lediglich dieses einfache Rätsel lösen:\n\nHier finden sich gleich zwei Brücken.\nDie einsame Palme biegt sich in Richtung Ufer.\nSucht bei den Kokosnüssen.\n\nViel Glück!", sourceObjective = "Löst das Rätsel und findet den Schatz.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[93105] = { id = 93105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorationsjagd", description = "Seid Ihr bereit für die heutige Herausforderung? Ich habe hier in der Nachbarschaft ein Stück aus meiner Sammlung versteckt. Um es zu finden, müsst Ihr lediglich dieses einfache Rätsel lösen:\n\nDer größte Jäger der Meere.\nHängt in der salzigen Luft.\nSucht unter der Plattform.\n\nViel Glück!", sourceObjective = "Löst das Rätsel und findet den Schatz.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[93106] = { id = 93106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorationsjagd", description = "Seid Ihr bereit für die heutige Herausforderung? Ich habe hier in der Nachbarschaft ein Stück aus meiner Sammlung versteckt. Um es zu finden, müsst Ihr lediglich dieses einfache Rätsel lösen:\n\nHeiße Luft füllt den Stoff.\nDer Bohlenweg krönt den Steinbogen.\nSucht dort, wo die Pfade sich kreuzen.\n\nViel Glück!", sourceObjective = "Löst das Rätsel und findet den Schatz.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
