quests[93143] = { id = 93143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorationsjagd", description = "Seid Ihr bereit für die heutige Herausforderung? Ich habe hier in der Nachbarschaft ein Stück aus meiner Sammlung versteckt. Um es zu finden, müsst Ihr lediglich dieses einfache Rätsel lösen:\n\nBlick auf die Felder.\nBüschel voller Blüten und Saat.\nSucht hinten nach Ware.\n\nViel Glück!", sourceObjective = "Löst das Rätsel und findet den Schatz.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[93147] = { id = 93147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorationsjagd", description = "Seid Ihr bereit für die heutige Herausforderung? Ich habe hier in der Nachbarschaft ein Stück aus meiner Sammlung versteckt. Um es zu finden, müsst Ihr lediglich dieses einfache Rätsel lösen:\n\nHöchster Sitz der Wyvern.\nKreisen über der See.\nSeht in der Mitte nach.\n\nViel Glück!", sourceObjective = "Löst das Rätsel und findet den Schatz.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[93148] = { id = 93148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorationsjagd", description = "Seid Ihr bereit für die heutige Herausforderung? Ich habe hier in der Nachbarschaft ein Stück aus meiner Sammlung versteckt. Um es zu finden, müsst Ihr lediglich dieses einfache Rätsel lösen:\n\nÜber sanfte Wasserfälle.\nZerstörte Brücke, die Ketten gaben nach.\nSeht am östlichen Ende nach.\n\nViel Glück!", sourceObjective = "Löst das Rätsel und findet den Schatz.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[93149] = { id = 93149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorationsjagd", description = "Seid Ihr bereit für die heutige Herausforderung? Ich habe hier in der Nachbarschaft ein Stück aus meiner Sammlung versteckt. Um es zu finden, müsst Ihr lediglich dieses einfache Rätsel lösen:\n\nOben schmieden Schmuggler Intrigen.\nUnten stehen Tortollaner hinter der Theke.\nDurchsucht den Seetang.\n\nViel Glück!", sourceObjective = "Löst das Rätsel und findet den Schatz.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[93150] = { id = 93150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorationsjagd", description = "Seid Ihr bereit für die heutige Herausforderung? Ich habe hier in der Nachbarschaft ein Stück aus meiner Sammlung versteckt. Um es zu finden, müsst Ihr lediglich dieses einfache Rätsel lösen:\n\nEine geheime Tierhöhle.\nVerborgen hinter schmalem Wasserfall.\nDurchsucht die Oase.\n\nViel Glück!", sourceObjective = "Löst das Rätsel und findet den Schatz.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[93151] = { id = 93151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorationsjagd", description = "Seid Ihr bereit für die heutige Herausforderung? Ich habe hier in der Nachbarschaft ein Stück aus meiner Sammlung versteckt. Um es zu finden, müsst Ihr lediglich dieses einfache Rätsel lösen:\n\nDas Feuer verlöscht nie.\nVersammelt Euch für Trauer oder Freude.\nSucht hinter dem Brennholz.\n\nViel Glück!", sourceObjective = "Löst das Rätsel und findet den Schatz.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[93152] = { id = 93152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorationsjagd", description = "Seid Ihr bereit für die heutige Herausforderung? Ich habe hier in der Nachbarschaft ein Stück aus meiner Sammlung versteckt. Um es zu finden, müsst Ihr lediglich dieses einfache Rätsel lösen:\n\nLeben regt sich aus trockener Erde.\nEin Lager, in dem Fischer ruhen können.\nEin Feuer wärmt den Schatz.\n\nViel Glück!", sourceObjective = "Löst das Rätsel und findet den Schatz.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[93382] = { id = 93382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entschuldigt die Störung", description = "{name}! Schön, Euch zu sehen. Die Verteidiger in der Festung könnten Eure Hilfe gebrauchen.\n\nEine der Gnome hat einen Roboter gebaut, der bei der Verteidigung der Feste helfen soll. Allerdings dreht er jedes Mal durch, wenn man ihn anschaltet.\n\nSie braucht jemanden, der die Angriffe des Roboters unterbricht, damit er repariert werden kann.\n\nKönntet Ihr etwas Zeit dafür erübrigen?", sourceObjective = "Aktiviert Kampfbot 11.2.7, unterbrecht dann seine Fähigkeiten 3-mal mit Eurer Teufelswache oder Eurem Teufelsjäger.", completion = "Hervorragende Arbeit! Jetzt sollte ich Zeit haben, den Fehler zu beheben, der ursprünglich dafür verantwortlich ist.\n\nVielleicht sollte ich einfach so tun, als wäre es Absicht gewesen, und es gut sein lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[93452] = { id = 93452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geborgenes zerknittertes Geschenk", description = "<Die Schergen des Griesgrams sind offenbar geflohen und haben ein kleines, ramponiertes, aber noch verwendbares Geschenk hinterlassen.\n\nVielleicht kann einer der Organisatoren der Winterfestlichkeiten dabei behilflich sein, es dem ursprünglich angedachten Empfänger zukommen zu lassen.>", sourceObjective = "Sprecht mit Joanna Kupferzwick in der Nachbarschaft an der Klingenschluchtküste.", sourceObjectiveStatus = "unverified-source-field" }
quests[93647] = { id = 93647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holz für Euch", sourceObjective = "Ihr seht wie jemand aus, der sich gut im Holzfäll'n mach'n würd'.\n\nHier, ich zeig' Euch, woran Ihr Bäume erkennt, die sich zum Fäll'n eignen.\n\nHolz is' für viele Dinge in Euerm Haus nützlich. Oder auch für andere Häuser, wenn Ihr was verschenk'n oder verkauf'n wollt. Ich wette, die alten Handwerkslehrer, von denen Ihr gelernt habt, hab'n neue Dinge anzubiet'n.\n\nGeht da raus un' schaut, was sich so mach'n lässt!", sourceObjectiveStatus = "unverified-source-field" }
quests[93877] = { id = 93877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional Objectives - Sequential", description = "{name}! Schön, Euch zu sehen. Die Verteidiger in der Festung könnten Eure Hilfe gebrauchen.\n\nEine der Gnome hat einen Roboter gebaut, der bei der Verteidigung der Feste helfen soll. Allerdings dreht er jedes Mal durch, wenn man ihn anschaltet.\n\nSie braucht jemanden, der die Angriffe des Roboters unterbricht, damit er repariert werden kann.\n\nKönntet Ihr etwas Zeit dafür erübrigen?", sourceObjective = "Aktiviert Kampfbot 11.2.7, unterbrecht dann seine Fähigkeiten 1-mal mit Eurer Teufelswache oder Eurem Teufelsjäger.", sourceObjectiveStatus = "unverified-source-field" }
quests[93878] = { id = 93878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional Objectives - Multiple Steps, No Sequence", description = "{name}! Schön, Euch zu sehen. Die Verteidiger in der Festung könnten Eure Hilfe gebrauchen.\n\nEine der Gnome hat einen Roboter gebaut, der bei der Verteidigung der Feste helfen soll. Allerdings dreht er jedes Mal durch, wenn man ihn anschaltet.\n\nSie braucht jemanden, der die Angriffe des Roboters unterbricht, damit er repariert werden kann.\n\nKönntet Ihr etwas Zeit dafür erübrigen?", sourceObjective = "Aktiviert Kampfbot 11.2.7, unterbrecht dann seine Fähigkeiten 1-mal mit Eurer Teufelswache oder Eurem Teufelsjäger.", sourceObjectiveStatus = "unverified-source-field" }
quests[93879] = { id = 93879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional Objectives - Conditional After Sequence", description = "{name}! Schön, Euch zu sehen. Die Verteidiger in der Festung könnten Eure Hilfe gebrauchen.\n\nEine der Gnome hat einen Roboter gebaut, der bei der Verteidigung der Feste helfen soll. Allerdings dreht er jedes Mal durch, wenn man ihn anschaltet.\n\nSie braucht jemanden, der die Angriffe des Roboters unterbricht, damit er repariert werden kann.\n\nKönntet Ihr etwas Zeit dafür erübrigen?", sourceObjective = "Aktiviert Kampfbot 11.2.7, unterbrecht dann seine Fähigkeiten 1-mal mit Eurer Teufelswache oder Eurem Teufelsjäger.", sourceObjectiveStatus = "unverified-source-field" }
quests[94210] = { id = 94210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Nest polstern", description = "Ein Haus wird erst durch die richtige Einrichtung zu einem Heim. Es schienen einige Händler in der Stadt zu sein. Vielleicht lohnt es sich, deren Angebote durchzusehen.", sourceObjective = "Findet heraus, wo Ihr Dekorationen bekommt.", progress = "Habt Ihr alle hiesigen Händler getroffen? Sie haben einige gute Möbel vorrätig.", completion = "Konntet Ihr gute Stücke für Euer Haus finden? Wir hoffen, dass uns in der Zukunft weitere Händler besuchen werden, also schaut gelegentlich vorbei!", sourceObjectiveStatus = "unverified-source-field" }
quests[94379] = { id = 94379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der alte Herd", description = "Wie es aussieht, ist Euer Haus bereit für den Ausbau. Normalerweise geht das nicht so schnell, aber Ihr habt hier im Ort wirklich Eindruck hinterlassen.\n\nLasst Euch von unserem Baumeister erklären, wie es weitergeht.", sourceObjective = "Wertet Euer Haus auf.", completion = "Wie lief die Renovierung? Hoffentlich habt Ihr nun genug Stauraum für all die Schätze, die Ihr auf Euren Abenteuern erbeutet.\n\nSchaut wieder beim Baumeister vorbei, wenn Ihr bereit für die nächste Aufwertung seid.\n\nOh, und es ist ein Brief für Euch angekommen, als Ihr unterwegs wart.", sourceObjectiveStatus = "unverified-source-field" }
quests[94455] = { id = 94455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich zu Hause", description = "Es ist Zeit, ein neues Kapitel aufzuschlagen.", sourceObjective = "Geht zur Eingangstür und betretet Euer neues Haus.", sourceObjectiveStatus = "unverified-source-field" }
quests[94847] = { id = 94847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vorbereitungen laufen", description = "Wie Ihr Euch vielleicht erinnert oder auch nicht, habe ich früher jungen Paladinen dabei geholfen, ihr erstes gepanzertes Reittier zu erhalten.\n\nDas war eine mühsame Aufgabe, bei der man monatelang Materialien sammeln und kreuz und quer durch Azeroth reisen musste.\n\nZum Glück haben die Zeiten sich geändert und wir haben jetzt die meisten dieser Materialien verfügbar. Gleichwohl möchte ich Euch helfen, ein neues Reittier zu bekommen, eins, das Eurem Titel als Hochlord angemessen ist.\n\nDamit wir beginnen können, müsst Ihr nur ein Geschirr für uns besorgen. Eins, das robust und schwer ist.", sourceObjective = "Beschafft ein Steinbalgledergeschirr von einem Lederverarbeiter. Ihr dürft es auch aus dem Auktionshaus beschaffen, wenn Ihr kein Lederverarbeiter seid oder keinen kennt.", sourceObjectiveStatus = "unverified-source-field" }
quests[94850] = { id = 94850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Ihr es baut", description = "Wenn wir eine dauerhafte Verbindung nach Xoroth aufbauen wollen, brauchen wir ein ganz besonders widerstandsfähiges Portal. Leider können wir so eines nicht einfach so herbeibeschwören.\n\nIhr müsst die notwendigen Materialien beschaffen. Sobald wir diese haben, werde ich dafür sorgen, dass es von den Mo'arg sofort gebaut wird.\n\nHier ist die Liste der Dinge, die Ihr benötigt.", sourceObjective = "Sammelt 5 Stück Teufelsschiefer, 3 Chaosspinelle und einen unbeugsamen Trank. Diese können entweder selbst gesammelt oder durch Handwerksfertigkeiten hergestellt oder im Auktionshaus gekauft werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[94932] = { id = 94932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindungen des Windlords", description = "Jetzt, da Donneraan erneut der Lord des Himmelswalls ist, könnten wir vielleicht im Austausch gegen diese verfluchten Bindungen ein Abkommen treffen. Aber denkt daran: Eine allein ist nicht ausreichend.\n\nKehrt mit beiden Bindungen und ausreichend mächtigem Erz, um sie zu binden, zu mir zurück. Dann werde ich Euch eine Audienz bei Donneraan dem Windlord verschaffen.", sourceObjective = "Besorgt beide Bindungen des Windlords und 10 Stücke Infernoschwefel.", sourceObjectiveStatus = "unverified-source-field" }
